WoWFQ[92319] = { t = "خواهشی از جنس تبر", d = "من و Kurdran بعد از اینکه با Khadgar، Turalyon و Alleria Horde را عقب راندیم، بیست سال در Outland، آن‌سوی Dark Portal بودیم.\nروزهای خوبی هم بود، اما هر روزی که از Honor Hold بیدار نشم، همان روز خوبی است.\nهمه آن مدت، Kurdran با گرایفونش، Sky'ree، دیده‌بان‌های ما را رهبری می‌کرد. و موقع خروج از Honor Hold، کوتاه و تند پرواز می‌کرد و از همه چیزهایی که orcها به‌سویش پرتاب می‌کردند سُر می‌خورد. به نظرم خنده‌دار می‌شود اگر بروی چند یادگاری برایش پیدا کنی!", o = { "به Hellfire Peninsula در Outland برو و 10 Rusty Battleaxe بازیابی کن. به‌اختیار، Scarred Spear را هم از درون Hellfire Ramparts جمع کن.", "با درگاه Khadgar به Hellfire Peninsula رفت", "Rusty Axe را جمع کن (10)" }, p = "چه خبر، <name>؟ چیزی برای من داری؟", c = "چرا این تبرهای زنگ‌زده قدیمی رو برای من میاری؟\nشبیه همون‌هایی‌ان که orcها تو Hellfire به سمت من پرت می‌کردن...\nعجیبه که یه orc چقدر می‌تونه تبر بندازه! باید حواس‌مون جمع باشه، وگرنه همون‌جا جا می‌موندیم.\nصبر کن، نکنه Danath تو رو فرستاده... البته که فرستاده.\nفقط یه چیز از دوری طولانی از خونه سخت‌تر بود: تحمل شوخ‌طبعی Danath همه اون مدت.\nنمی‌دونم کدوم بیشتر به هدف نمی‌خورد--تبرها یا جوک‌هاش!\nاما به‌عنوان رفیق، همیشه وسط خالی می‌زنه..." }
WoWFQ[92320] = { t = "هنوز پشت درگاه‌های دشمن", d = "حین مرور خاطرات گذشته، یادگاری به یادمان آمد که در جنگ‌مان با Burning Legion بازیابی‌اش نکرده بودیم.\nاین شی ظرفی از شرارت بزرگ است و نباید در چنگ نیروهای شیطانی باقی‌مانده بماند.\nبرای رسیدن به آن، باید به Broken Shore سفر کنیم؛ جایی که Tehd درگاهی دارد که برای استفاده ما بازسازی کرده است. به این شکار می‌پیوندی؟", o = { "به Broken Shore سفر کن و یادگار شرارت بزرگ را بازیابی کن. به‌اختیار، Corrupted Lantern را هم به دست بیاور.", "وارد Hijacked Portal شو", "روی Derelict Legion Vessel با Tehd صحبت کن", "موجودی غارت شد", "Dark Chest of Forbidden Evils را جمع کن (10)", "از Toy Box ات از Personal Key to the Arcantina استفاده کن" }, p = "باید بار اول بازیابی‌اش می‌کردیم.", c = "می‌بینم ظرف را پیدا کردی. خوب است. می‌گیریمش و مطمئن می‌شویم به دست‌های درست برسد." }
WoWFQ[92321] = { t = "شماره‌ای یخ‌زده", d = "من و Tarenar از آن‌سوی Plaguelandsها قصه تهاجم به Icecrown Citadel را شنیده بودیم.\nاما حسابی گمراه است!\nاین الف گمان می‌کند در Ashen Verdict فرمانده‌های Ebon Blade بیشتر از Argent Crusade بودند. کاملا حماقت است. واضح است که paladinها بیشتر بودند!\nمی‌شود بروی توی Icecrown Citadel بگردی و برایم مدرکی پیدا کنی؟ از بحث با او بیزارم!", o = { "8 Frostbitten Tabard را در Icecrown Citadel پیدا کن. به‌اختیار، Ebon Banner را هم از Icecrown Citadel به دست بیاور.", "با درگاه Khadgar به Icecrown رفت", "Frostbitten Tabard را جمع کن (8)" }, p = "چیزی پیدا نکردی هنوز؟ فقط چیزی می‌خواهم که به Tarenar ثابت کند حق با من است.", c = "اوه، این سینه‌پهن‌ها حسابی آسیب دیده‌اند. به گمانم از بعضی یادگارهای قدیمی نمی‌شود فهمید کدام طرف نیروی بیشتری فرستاد.\nبه هر روی، حالا سر این بحثیم که کدام‌مان در Broken Shore کمتر خوابید.\nبه نظر می‌رسد پرچمی از Ebon Blade به دست آوردی و هنوز زنده‌ای که قصه‌اش را بگویی. جای نزدیک‌ای در Arcantina هست که آویزانش کنی." }
WoWFQ[92322] = { t = "Timear آینده‌ی مرگی را پیش‌بینی می‌کند!", d = "سلام، <name>. لحظه‌ای وقت داری؟\nچیز مهمی است که حین تهاجم به Isle of Thunder گم کردم: ساعت جیبی‌ای که دوست قدیمی‌ام، Archmage Timear، به من هدیه داده بود. بله، همان Timear... همان که آینده را می‌بیند. به من گفت چنین روزی می‌رسد و تو به من کمک می‌کنی.\nساعت را Council of Elders برداشت؛ دقیق‌تر بگویم High Priestess Mar'li. اگر به آن جزیره بروی و از Throne of Thunder پس بگیری--و هر دو می‌دانیم که می‌روی--من راهت می‌اندازم.", o = { "به Isle of Thunder سفر کن و وارد Throne of Thunder شو. درونش، Lan'dalock's Pocket Watch را بازیابی کن. به‌اختیار، Ancient Zandalari Scroll را هم به دست بیاور.", "با درگاه Lan'dalock به Isle of Thunder برو", "Lan'dalock's Pocket Watch را بردار" }, p = "پیشگویی Timear درست از آب درآمد؟ ساعت جیبی‌ام را پس گرفتی؟\nیا فقط برگشتی که از جمع دلپذیر من لذت ببری؟", c = "البته که موفق شدی. Timear در این جور چیزها به‌طرز غیرقابل‌تحملی همیشه حق دارد. و حالا برگشته تا دستش را زیر بینی‌ام بمالد.\nقدردانتم.\nبه نظر می‌رسد یک Ancient Zandalari Scroll هم پیدا کرده‌ای. Timear از قبل دیده که در Arcantina به نمایش درمی‌آید. جایی برای گذاشتنش پیدا کن." }
WoWFQ[92323] = { t = "جایی که روزی آتش می‌سوخت", d = "باورش سخت است، نه؟ Horde و Alliance، یک اتاق، بدون خنجر.\nداشتم از روزهایم در Firelands می‌گفتم، وقتی lucifern جمع می‌کردم. چه بوی مخصوصی داشتند... جایی میان دود و چیزی خیلی وقت مرده. مدتی گذشته و تقریبا دلم تنگش شده.\nچند تایشان را برای من و Zen'tabra بگیری، شود؟ او سزاوار تجربه کاملش است.", o = { "به Mount Hyjal سفر کن و وارد Firelands شو. درونش، 8 Lucifern بازیابی کن. به‌اختیار، Evergreen Vine را هم به دست بیاور.", "با درگاه Khadgar به Firelands رفت", "Lucifern را جمع کن (8)" }, p = "امیدوارم آن lucifernها را پیدا کرده باشی--چون اگر نه، حال من خنجری می‌شود. خیلی خنجری.", c = "عجیب است که یک بو می‌تواند این‌همه خاطره را برگرداند. ممنون که اجازه دادم سهیم شوی.\nو... از همه بقیه عذرخواهی می‌کنم. بعضی خاطره‌ها قرار است بمانند.\nدر Firelands یک پیچک همیشه‌سبز پیدا کردی؟ اگر این نشانه امید نباشد، نمی‌دانم چیست.\nبه Arcantina بزن‌اش--شاید نخستین گیاهی باشد که اینجا فوری تسلیم نمی‌شود." }
WoWFQ[92324] = { t = "پرونده سرد Uncrowned", d = "شانس آوردیم که Uncrowned جان به در برد، و آرشیوش هم، به لطف Taoshi. داریم می‌خوانیم‌شان...\nشهر بزرگ highborne ها یعنی Dire Maul را شنیده‌ای؟ Uncrowned چشمش به شاهزاده خطرناک، Tortheldrin، بود، اما بعد از مرگش پرونده بایگانی شد.\nاین یادداشت‌ها می‌گویند شاید در ویرانه‌های شهر اشیای جالبی باشد؛ با اشاره ویژه به Nostro's Compendium of Dragon Slaying. آن کتاب مدتی پیش بازیابی شد، اما کم کسی می‌داند که چند فصلش گم بود.\nبگذار پرونده را دوباره باز کنیم.", o = { "به Feralas سفر کن و 8 Lost Page از Nostro's Compendium جمع کن. به‌اختیار، Pylon Fragment را هم از Dire Maul به دست بیاور.", "با درگاه Khadgar به Feralas رفت", "Lost Page from Nostro's Compendium را جمع کن (8)" }, p = "محصور در گرمای خانه و رفقا، باورش سخت است که Dalaran واقعا رفته...\n<Kelsey با عمق صداقت به Taoshi نگاه می‌کند.>\nUncrowned در جمع کردن کارهایش وقت تلف نمی‌کند. چیز جالبی پیدا کرده‌ای؟", c = "چه شگفتی! به گمانم هر چیز این‌جوری تا حالا کامل غارت شده و خیلی، خیلی دور برده شده بود.\nکسی را پیدا می‌کنم که سراغ آن صفحه‌ها برود. خیلی کاتبان حاضرند برای ترجمه جادوی باستانی فرصتی داشته باشند.\nو Pylon Fragment را هم آورده‌ای؟ پس وارد Dire Maul شدی. چه یادگاری نفیس برای پرس‌وجوی بازدیدکنندگان آینده.\nبه نظرت بگذارش جایی در Arcantina." }
WoWFQ[92325] = { t = "میراث Hellscream", d = "خواهرم Krenna روزی Conqueror در ارتش‌های Horde بود. بی‌رحم. وحشی. بعضی‌ها می‌گفتند ستمگر. اما در جوانی فرق داشت. می‌ترسید، اما همیشه با من مهربان بود. با کسانی که راهشان می‌داد، گرم بود. آیا قدرت او را عوض کرد؟\nو اگر او را به ستمگر بدل کرد، آیا Garrosh Hellscream را هم عوض کرد؟ می‌دانم Krenna کی بود. نمی‌دانم Garrosh کی بود.\nبه Nagrand سفر کن و بفهم.", o = { "به Nagrand برو و کشف کن Garrosh در جوانی چه بود. به‌اختیار، Weathered Tome را هم به دست بیاور.", "با درگاه Khadgar به Nagrand رفت", "با Greatmother Geyah صحبت کن", "با Osrok the Immovable صحبت کن", "زره شکسته را تعمیر کن", "Practice Axe را بردار", "با Greatmother Geyah صحبت کن" }, p = "می‌خواهم بدانم رهبر پیشین Warsong واقعا کی بود.", c = "Hellscream توان نداشت، پس ساختش. غرور نداشت، تا وقتی به او هدیه شد. و با این حال... همیشه همین بود: اراده‌ای سخت و جان‌سختی.\nپس شاید قدرت آدم را عوض نمی‌کند--فقط نشان می‌دهد واقعا در عمق وجودش کیست.\nاین Greatmother Geyah خردمند است. باید روزی به دیدارش بروم.\nیک کتاب هم آورده‌ای که به نظر روزهای بهتری داشته. می‌توانم دانش عظیم درونش را تصور کنم.\nجای درستش همین‌جا در Arcantina است. لطفا جایی امن برایش پیدا کن." }
WoWFQ[92326] = { t = "عطر تپه‌های شنی", d = "دلم برای بوی بیابان تنگ شده. عطر آزادی در سرزمینی وحشی است. دوست دارم آن خاطره بویایی را تازه کنم.\nحین آنجایی، از کاروان‌ها چیزی بردار. این مکان به کمی روح کوچ‌نشینی نیاز دارد.\nشاید به Shatterstone Harbor هم سری بزنی و برای آقای بزرگ چیزی بگیری. شاید یک لنگر؟ بی‌نقص می‌شود! تصورش را بکن که دارد آن را این‌طرف و آن‌طرف می‌کشد.", o = { "به Vol'dun برو و یک Pouch of Fragrant Sands برگردان. به‌اختیار، Sandy Tapestry را از Vulpera Hideaway و Heavy Anchor را از Shatterstone Harbor هم به دست بیاور.", "Handful of Sand را جمع کن (20)", "Sack of Fragrant Sands را بردار" }, p = "کیسه را پر کردی؟", c = "آه! فقط بو کن، <name>.\nممنون که به روزگاری دیگر... و خانه برگرداندی‌ام.\nآن قالی را آویزان می‌کنی، شود؟ دوست دارم رفقایم در Arcantina را با ظریف‌ترین بافت vulpera آشنا کنم." }
WoWFQ[92327] = { t = "لحظه‌ای نسل‌ها", d = "همیشه خوشحالم که کسی با سابقه تو همچنان حوصله حرف زدن با ما پیرمردها را دارد، $p.\nمن و Eitrigg این روزها درباره میراث حرف می‌زنیم. می‌دانی هر دوی ما با Valarjar در برابر Legion جنگیدیم؟ جالب است که تاریخ‌های طولانی چطور در هم می‌تنند.\nاما میراث واقعی ما بچه‌هایمان‌اند. نمی‌دانم وقتی داری تا حال هر دو سر می‌زنی یا نه. حین آنجا، مطمئن شو مهارت‌هایشان تیز مانده است.", o = { "Eitrigg و Darius می‌خواهند با بچه‌هایشان مسابقه تمرینی بدهی.\nبه‌اختیار، Dried Roses را از Gilneas City در Ruins of Gilneas و Clefthoof Hide را از Blackrock Stronghold در Burning Steppes به دست بیاور.", "با درگاه Khadgar از Arcantina به Gilneas رفت", "Dried Roses از Greymane Court در Gilneas City گرفته شد", "در Gilneas با Lorna Crowley مسابقه تمرینی بده", "با درگاه Khadgar به Burning Steppes رفت", "Clefthoof Hide از Blackrock Stronghold گرفته شد", "در Burning Steppes با Ariok مسابقه تمرینی بده" }, p = "توانستی Lorna را پیدا کنی؟ پس پسر Eitrigg، یعنی Ariok، چه؟", c = "از قیافه‌ات می‌فهمم که بچه‌هایمان حسابی از خودشان کار درآوردند.\nخوب است بدانیم اگر خطر بزرگی سراغشان بیاید، مهارت‌هایشان هنوز تیز است.\nبه نظر می‌رسد حین آنجا در Blasted Lands یک پوست clefthoof هم پیدا کردی.\nEitrigg بهتر از من می‌داند، اما حتما از راه Dark Portal از Draenor آمده است.\nچیزی است که باید به نمایش دربیاید، و جای بهتری از همین Arcantina سراغ ندارم." }
WoWFQ[95779] = { t = "لحظه‌ها در یک پارچ", d = "کسی که راهش را با نوشیدنی بلد است، سزاوار بهترین دم‌کرده است. دقیقا چیزی برای رفیقم، Flynn، در سر دارم.\nمواد لازم را در آبجوشافی خانوادگی‌ام در Valley of Four Winds دارم. خودم می‌رفتم، اما یک brewmaster باید بلد باشد چه وقت بنشیند، نفس بکشد و از آنچه در پارچ است لذت ببرد.\nمی‌شود به Stormstout Brewery بروی و مواد را برایم بیاوری، رفیق؟", o = { "به Valley of Four Winds سفر کن و وارد Stormstout Brewery شو. درونش، 6 ماده اولیه بازیابی کن. به‌اختیار، Stormstout Brewery Lantern را هم به دست بیاور.", "با درگاه Khadgar به Valley of Four Winds رفت", "Stormstout Ingredients را جمع کن (6)" }, p = "توانستی مواد را بگیری؟", c = "به نظر می‌رسد مواد باکیفیتی هستند. حتما یک چیزهایی درباره دم‌کردن می‌دانی!\nممنونم، رفیق. اگر دوست داشتی امتحان کنی، برای تو هم به‌اندازه کافی می‌سازم!" }
WoWFQ[95780] = { t = "امیدی برای یتیمان", d = "من و Garona هیچ‌کدام سر گذشته‌مان زیاد حرف نمی‌زنیم. حرف زیادی هم برای گفتن نیست.\nبچه‌های آن یتیم‌خانه در Shattrath--دارند همان زندگی ما را می‌کنند. از تو نمی‌خواهم آن را درست کنی. از تو می‌خواهم حاضر شوی و به‌شان یادآوری کنی که دنیا چیزی دارد که ارزش جنگیدن دارد.\nبرای من، انتقام ارزش جنگیدن داشت. اما شاید آن‌ها آینده‌ای روشن‌تر داشته باشند.\nبرو با آن‌ها بازی کن. سعی کن نشانشان بدهی کسی که ارزش الگو گرفتن دارد واقعا چه شکلی است.", o = { "به یتیم‌خانه Shattrath سفر کن و با بچه‌ها بازی کن. به‌اختیار، Wooden Toy Sword را هم به دست بیاور.", "با درگاه Khadgar به Shattrath رفت", "گرم‌سنگ بازی شد (3)" }, p = "بچه‌ها حرف‌هایی می‌زنند که آدم را می‌خنداند و می‌لرزاند، نه...", c = "واقعا رفتی. مطمئن نبودم بروی.\nبچه‌ها یادشان می‌ماند. همیشه کسانی را که حاضر می‌شوند به یاد می‌آورند.\nاین شمشیر چوبی چیست که آنجاست؟ بگذار یک نگاه بندازم.\n<Vanessa و Garona شمشیر را برمی‌گردانند و متوجه حکاکی‌ای رویش می‌شوند.>\n\"برای یک قهرمان.\"\nجای خوبی در Arcantina برای آویزان کردنش هست." }
WoWFQ[96952] = { t = "بشکه قبض می‌گساری", c = "به میخانه‌های سراسر ناحیه‌های Midnight کمک مالی کن تا قبض‌ها پرداخت شود!" }
